import inspect, json

def task_func(func):
    # Get function name
    func_name = func.__name__

    # Determine if it's a lambda function
    is_lambda = (func_name == "<lambda>")

    # Get the signature and parameters
    sig = inspect.signature(func)
    args = []
    defaults = {}
    for name, param in sig.parameters.items():
        # consider positional or keyword parameters; ignoring *args and **kwargs
        if param.kind in (param.POSITIONAL_ONLY, param.POSITIONAL_OR_KEYWORD, param.KEYWORD_ONLY):
            args.append(name)
            if param.default is not inspect.Parameter.empty:
                defaults[name] = param.default

    # if no defaults were provided, set defaults to None.
    if not defaults:
        defaults_value = None
    else:
        defaults_value = defaults

    # Process annotations: 
    # Include 'return' if exists.
    annotations = {}
    for key, value in func.__annotations__.items():
        # If the annotation is None then output "None"
        if value is None:
            annotations[key] = "None"
        # If the annotation is a type, output its __name__
        elif isinstance(value, type):
            annotations[key] = value.__name__
        else:
            # Otherwise, use string representation
            annotations[key] = str(value)

    result = {
        "function_name": func_name,
        "args": args,
        "defaults": defaults_value,
        "annotations": annotations,
        "is_lambda": is_lambda
    }

    return json.dumps(result)

